int sumSubarrayMins(vector<int>& a) {
    const long long MOD = 1e9 + 7; int n = a.size();
    vector<long long> L(n), Rr(n); vector<int> st;
    for (int i = 0; i < n; i++) { while (!st.empty() && a[st.back()] > a[i]) st.pop_back(); L[i] = i - (st.empty() ? -1 : st.back()); st.push_back(i); }
    st.clear();
    for (int i = n - 1; i >= 0; i--) { while (!st.empty() && a[st.back()] >= a[i]) st.pop_back(); Rr[i] = (st.empty() ? n : st.back()) - i; st.push_back(i); }
    long long s = 0;
    for (int i = 0; i < n; i++) s = (s + a[i] * L[i] % MOD * Rr[i]) % MOD;
    return (int)s;
}
